import hashlib,json,os
from pathlib import Path
STAGE=Path(__file__).resolve().parent
ROOT=STAGE.parents[1]; OUT=ROOT/'outputs/mac-connected-subgroup01'; PROJ=STAGE/'project/ShielddSecurity'
DESC=ROOT/'outputs/mac-subgroup-descriptor01/subgroup01.json'
sha=lambda b:hashlib.sha256(b).hexdigest()
raw=DESC.read_bytes(); assert sha(raw)=='72cfd5fb64d080f1c1a96414c147de712091fd7a1bf93140ab7fd1172523e573'
d=json.loads(raw); ns='ShielddSecurity.TransferFirstSubgroupData01'
assert len(d['nodes'])==58 and len(d['constants'])==15 and len(d['inputs'])==7
assert [n['source_node'] for n in d['nodes']]==list(range(1,59))
assert [x['source_witness'] for x in d['inputs']]==list(range(11,18))
constant={c['source_constant']:c for c in d['constants']}; nodes={n['source_node']:n for n in d['nodes']}
local={(1,i):i-11 for i in range(11,18)}|{(0,c['source_constant']):i+7 for i,c in enumerate(d['constants'])}|{(2,j):j+21 for j in range(1,59)}
assert all(local[tuple(n[port])]<n['source_node']+21 for n in d['nodes'] for port in ['left','right'])
def terms(ref):
 k,i=ref
 return ([[0,constant[i]['integer']]] if constant[i]['integer'] else []) if k==0 else ([[i+3,1]] if k==1 else nodes[i]['expression']['terms'])
linear=lambda ts:'['+', '.join(f'({a}, {b})' for a,b in ts)+']'
pool=[]; poolids={}
def intern(ts):
 key=tuple(tuple(x) for x in ts)
 if key not in poolids:poolids[key]=len(pool);pool.append(ts)
 return 'lc'+str(poolids[key])
expr=[]; source=[]; hints=[]; steps=[]
for i in range(7):
 t=intern([[i+14,1]]);expr.append('.linear '+t);source.append(f'.input {i+11}');hints.append(f'.input {i+11} {t}')
for c in d['constants']:
 t=intern([[0,c['integer']]] if c['integer'] else []);expr.append('.linear '+t);source.append(f".constant {c['integer']}");hints.append(f".constant {c['integer']} {t}")
rows=d['indexed_original_rows']; assert len(rows)==71
arith=[r for r in rows if r['origin']['kind']=='node']+[rows[-1]]; assert len(arith)==65
rowindex={r['capture_index']:i for i,r in enumerate(arith)}
fin=lambda i,n=80:f'⟨{i}, by change {i} < {n}; decide⟩'
for n in d['nodes']:
 ordinal=n['source_node']+21; l,r=[local[tuple(n[p])] for p in ['left','right']]; x,y=[intern(terms(n[p])) for p in ['left','right']]; z=intern(n['expression']['terms'])
 expr.append('.'+n['expression']['kind']+' '+z); source.append('.'+n['operation']+' '+fin(l,ordinal)+' '+fin(r,ordinal))
 c=n['certificate']; ctor=c['constructor']; args=f'{fin(l,ordinal)} {fin(r,ordinal)} {x} {y} {z}'
 if ctor in ['foldedLeft','foldedRight']:args+=' '+str(c['coefficient'])
 if ctor=='square':
  args+=' '+str(rowindex[c['rows'][0]]); assert n['expression']['terms'][0][1]==1 and len(n['expression']['terms'])==1
  steps.append(f'.square {x} [] {n["expression"]["terms"][0][0]}')
 if ctor=='product':
  aux=intern(c['auxiliary']);args+=' '+aux+' '+' '.join(str(rowindex[v]) for v in c['rows'])
  assert len(c['auxiliary'])==len(n['expression']['terms'])==1 and c['auxiliary'][0][1]==n['expression']['terms'][0][1]==1
  steps.append(f'.product {x} {y} [] {n["expression"]["terms"][0][0]} {c["auxiliary"][0][0]}')
 hints.append('.'+ctor+' '+args)
assertions=[]; assertion_hints=[]; assertion_steps=[]
for i,a in enumerate(d['assertions']):
 c=a['certificate'];assert c['constructor']=='linear' and len(c['rows'])==1
 l,r=[local[tuple(c[p])] for p in ['left','right']];x,y=[intern(terms(c[p])) for p in ['left','right']]
 assertions.append(f'({fin(l)}, {fin(r)})'); assertion_hints.append((l,r,f'.linear {x} {y} {64+i}'));assertion_steps.append(f'.equal {x} {y}')
rowdefs=[]
for i,row in enumerate(rows):rowdefs.append(f'def row{i} : Row := ⟨{intern(row["a"])}, {intern(row["b"])}⟩')
header=['-- GENERATED by generate_subgroup.py; edit the generator.', 'import ShielddSecurity.CompilerIndexed01','import ShielddSecurity.CompilerCompletion','set_option maxHeartbeats 400000','set_option maxRecDepth 4096',f'namespace {ns}','open Compiler CompilerCompletion CompilerIndexed01']
def audits(names):
 return sum(([f'set_option pp.all true in',f'#check @{ns}.{n}',f'#print axioms {ns}.{n}'] for n in names),[])
def save(name,lines):
 path=PROJ/(name+'.lean'); b=('\n'.join(lines)+'\n').encode()
 if path.exists() and path.read_bytes()!=b:
  hist=OUT/'source-history';hist.mkdir(exist_ok=True);old=path.read_bytes();(hist/(name+'-'+sha(old)+'.lean')).write_bytes(old)
 tmp=path.with_suffix('.tmp');tmp.write_bytes(b);os.replace(tmp,path)
 return {'path':str(path.relative_to(ROOT)),'sha256':sha(b),'bytes':len(b)}
records=[]; split=len(pool)//2
for which,lo,hi in [(1,0,split),(2,split,len(pool))]:
 lines=header.copy()
 if which==2:lines.insert(1,'import ShielddSecurity.TransferFirstSubgroupTables01')
 lines += [f'def lc{i} : Linear := '+linear(pool[i]) for i in range(lo,hi)]
 if which==2:lines+=rowdefs
 lines += [f'end {ns}']
 records.append(save(f'TransferFirstSubgroupTables0{which}',lines))
lines=header.copy();lines.insert(1,'import ShielddSecurity.TransferFirstSubgroupTables02')
lines += [f'def p : Nat := {d["modulus"]}',f'def copy : Nat := {d["constant_copy"]}','def inputTerms (i : Nat) : Linear := [(3+i,1)]','def originalRows : Array Row := #['+', '.join('row'+str(i) for i in range(71))+']','def arithmeticRows : Array Row := #['+', '.join('row'+str(i) for i in range(64))+', row70]','def captureIndices : Array Nat := #['+', '.join(str(r['capture_index']) for r in rows)+']','def node (index : Fin 80) : SourceNode index.val := match index with']
lines += [f'  | ⟨{i}, _⟩ => {v}' for i,v in enumerate(source)]+['  | ⟨n+80, h⟩ => False.elim (by omega)','def expressions (index : Fin 80) : Expression := match index.val with']
lines += [f'  | {i} => {v}' for i,v in enumerate(expr)]+['  | _ => .linear []','def hints (index : Fin 80) : Hint index.val := match index with']
lines += [f'  | ⟨{i}, _⟩ => {v}' for i,v in enumerate(hints)]+['  | ⟨n+80, h⟩ => False.elim (by omega)','theorem input_bound (index : Fin 80) (input : Nat) (h : node index = .input input) : input < 22735 := by','  rcases index with ⟨n, hn⟩','  have cases : '+' ∨ '.join(f'n = {i}' for i in range(80))+' := by omega','  rcases cases with '+' | '.join('h'+str(i) for i in range(80)),'  all_goals subst n; simp [node] at h','  all_goals omega','-- Outputs are the selected computed subgroup point, not runtime circuit outputs.','def graph : SourceGraph 22735 80 := ⟨node,input_bound,['+', '.join(assertions)+'],['+fin(76)+', '+fin(79)+']⟩','def assertionHints (ports : Fin 80 × Fin 80) : AssertionHint := match ports.1.val,ports.2.val with']
lines += [f'  | {l},{r} => {h}' for l,r,h in assertion_hints]+['  | _,_ => .linear [] [] 0','def materializedSteps : List Step := ['+',\n  '.join(steps)+']','def assertionSteps : List Step := ['+',\n  '.join(assertion_steps)+']','def copyStep : Step := .equal [(0,1)] [(0,1)]','def arithmeticSteps : List Step := materializedSteps ++ [copyStep]','def allSteps : List Step := materializedSteps ++ assertionSteps ++ [copyStep]','def emittedArithmetic : Array Row := (emitted arithmeticSteps).toArray','def emittedOriginal : Array Row := (emitted allSteps).toArray','def arithmeticMapping : Array Nat := (List.range 65).toArray','def originalMapping : Array Nat := (List.range 71).toArray','def nodeInclusionMapping : Array Nat := ((List.range 64)++[70]).toArray','theorem graph_shape : graph.assertions.length=6 ∧ graph.outputs.length=2 := by decide +kernel','theorem rows_shape : originalRows.size=71 ∧ arithmeticRows.size=65 := by decide +kernel',f'end {ns}']+audits(['input_bound','graph_shape','rows_shape'])
records.append(save('TransferFirstSubgroupData01',lines))
for which,start,size in [(1,0,54),(2,54,26)]:
 leaf=f'ShielddSecurity.TransferFirstSubgroupLeaf0{which}';lines=['-- GENERATED by generate_subgroup.py; edit the generator.','import ShielddSecurity.TransferFirstSubgroupData01','set_option maxHeartbeats 600000','set_option maxRecDepth 8192',f'namespace {leaf}',f'open {ns} Compiler CompilerIndexed01',f'def indices : List (Fin 80) := (List.finRange {size}).map (fun i => ⟨i.val+{start}, by omega⟩)','theorem checked : checkBlock p copy arithmeticRows inputTerms graph expressions hints indices = true := by decide +kernel','theorem certificates (index : Fin 80) (member : index ∈ indices) :','    NodeCertificate p (unoutlineRows copy arithmeticRows.toList) inputTerms','      (graph.prior expressions index) (graph.node index) (expressions index) :=','  checkBlock_sound p copy arithmeticRows inputTerms graph expressions hints indices checked index member',f'end {leaf}']
 for n in ['checked','certificates']:lines += ['set_option pp.all true in',f'#check @{leaf}.{n}',f'#print axioms {leaf}.{n}']
 records.append(save(f'TransferFirstSubgroupLeaf0{which}',lines))
ans='ShielddSecurity.TransferFirstSubgroupAssertionCompletion01'
lines=['-- GENERATED by generate_subgroup.py; edit the generator.','import ShielddSecurity.TransferFirstSubgroupCompletion01','set_option maxHeartbeats 500000','set_option maxRecDepth 8192',f'namespace {ans}',f'open Compiler CompilerCompletion {ns}','variable {F : Type} [Field F]',
 'theorem assertion_steps_legal (rho : Nat → F)',
 '    (truth : ∀ ports ∈ graph.assertions, expressionValue rho (expressions ports.1) = expressionValue rho (expressions ports.2)) :',
 '    ∀ step ∈ assertionSteps, step.Legal rho := by',
 '  intro step member','  simp only [assertionSteps,List.mem_cons,List.not_mem_nil,or_false] at member',
 '  rcases member with '+' | '.join('case'+str(i) for i in range(6))]
for i,(l,r,_) in enumerate(assertion_hints):
 lines += [f'  · subst step',f'    have h := truth ({fin(l)}, {fin(r)}) (by decide +kernel)',
           '    exact h']
lines += [f'end {ans}','set_option pp.all true in',f'#check @{ans}.assertion_steps_legal',f'#print axioms {ans}.assertion_steps_legal']
records.append(save('TransferFirstSubgroupAssertionCompletion01',lines))
assert DESC.read_bytes()==raw
receipt={'schema':'connected-subgroup-generated-v1','descriptor_sha256':sha(raw),'generator_sha256':sha(Path(__file__).read_bytes()),'typed_nodes':80,'arithmetic_source_nodes':58,'input_nodes':7,'constant_nodes':15,'row_count':71,'arithmetic_rows':65,'unique_lcs':len(pool),'max_lc_terms':max(map(len,pool)),'assertion_pairs':[[local[tuple(a['certificate'][p])] for p in ['left','right']] for a in d['assertions']],'sources':records,'full_transfer':'OPEN'}
i=1
while (OUT/f'generation-{i:02d}.json').exists():i+=1
(OUT/f'generation-{i:02d}.json').write_text(json.dumps(receipt,indent=2)+'\n');print(json.dumps(receipt))
